# 运费计算：订单商品净额达到门槛则包邮，否则收取固定运费。
# 金额单位为分，全部为整数。


def shipping_fee(order_total_cents, refunded_cents, free_threshold_cents, fee_cents):
    """返回该订单应收运费（整数分）。"""
    if order_total_cents < 0 or refunded_cents < 0 or fee_cents < 0:
        raise ValueError("amounts must be non-negative")
    if refunded_cents > order_total_cents:
        raise ValueError("refund cannot exceed order total")

    net_cents = order_total_cents - refunded_cents
    # 错误：包邮门槛用的是退款前的下单金额。
    if order_total_cents >= free_threshold_cents:
        return 0
    return fee_cents

